mapper.select:
select c.id, c.name, c.type, c.full_money, c.minus, c.rate, c.start_time, c.end_time, c.total_count, c.received_count, c.limit_per_user, c.status, c.create_time, c.update_time, case when c.total_count = 0 then null else c.total_count - c.received_count end as remain_count, (select count(*) from user_coupon uc where uc.coupon_id = c.id and uc.status = 1) as used_count from coupon c
and c.name like concat('%', #{name}, '%')
and c.type = #{type}
and c.status = #{status}
order by c.id desc

mapper.insert:
insert into coupon (
    name, type, full_money, minus, rate, start_time, end_time,
    total_count, received_count, limit_per_user, status,
    create_time, update_time, create_user, update_user
) values (
    #{name}, #{type}, #{fullMoney}, #{minus}, #{rate}, #{startTime}, #{endTime},
    #{totalCount}, #{receivedCount}, #{limitPerUser}, #{status},
    #{createTime}, #{updateTime}, #{createUser}, #{updateUser}
)

mapper.update:
update coupon
name = #{name}, type = #{type}, full_money = #{fullMoney}, minus = #{minus}, rate = #{rate}, start_time = #{startTime}, end_time = #{endTime}, total_count = #{totalCount}, limit_per_user = #{limitPerUser}, status = #{status}, update_time = #{updateTime}, update_user = #{updateUser},
where id = #{id}

update coupon
set status = #{status}
, update_time = #{updateTime}
, update_user = #{updateUser}
where id = #{id}

update coupon
set received_count = received_count + 1,
    update_time = #{now}
where id = #{id}
  and status = 1
  and start_time <= #{now}
  and end_time >= #{now}
  and (total_count = 0 or received_count < total_count)
